                        mb_regex_groups_iter_args args = {
                                return_value,
                                Z_STRVAL(MBREX(search_str)),
                                len,
                                MBREX(search_regs)
                        };
                        onig_foreach_name(MBREX(search_re), mb_regex_groups_iter, &args);
